// ROUND-004 B1: generic cluster array (weak -> strong). Defined here; declared
// extern in aatped_topology.h.
std::vector<CpuCluster> g_clusters;

std::set<int> parseAffinityMask(const std::string& maskStr) {
    std::set<int> cpus;
    std::string s = maskStr;
    trim(s);
    if (s.empty()) return cpus;
    // LED-101 (R7-016): g_cpuCount is written under g_topologyRwMutex; snapshot it
    // once so the range-clamp below uses a consistent value.
    int cpuCount;
    {
        std::lock_guard<std::mutex> topoLk(g_topologyRwMutex);
        cpuCount = g_cpuCount;
    }
    int maxCpu = (cpuCount > 0) ? cpuCount - 1 : 0;
    // "ffffffff" or "ff" means all CPUs
    bool allHex = true;
    for (char c : s) {
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
            allHex = false; break;
        }
    }
    // G6-014: a single-byte mask "ff" (size==2) was previously skipped by the
    // `> 2` guard and fell through to range parsing (stoi("ff") -> empty set).
    // Accept any pure-hex string; clamp expansion to the actual cpu count (G6-015).
    if (allHex && s.size() >= 2) {
        // D-04: Proper hex mask parsing - interpret as bitmask
        try {
            unsigned long long mask = std::stoull(s, nullptr, 16);
            int bits = std::min((int)topology::kHexBitWidth, cpuCount);
            for (int i = 0; i < bits; i++) {
                if (mask & (1ULL << i)) cpus.insert(i);
            }
        } catch (...) {
            // Fallback: all CPUs — use the snapshotted local cpuCount taken
            // under g_topologyRwMutex above, not the global g_cpuCount (which
            // could be racing a concurrent topology rebuild).
            LOG_WARN("parseAffinityMask: hex mask '%s' unparsable, falling back to all %d cpus",
                     s.c_str(), cpuCount);
            for (int i = 0; i < cpuCount && i < topology::kHexBitWidth; i++) cpus.insert(i);
        }
        return cpus;
    }
    // Parse comma-separated ranges
    std::stringstream ss(s);
    std::string token;
    while (std::getline(ss, token, ',')) {
        trim(token);
        if (token.empty()) continue;
        size_t dash = token.find('-');
        if (dash != std::string::npos) {
            try {
                int lo = std::stoi(token.substr(0, dash));
                int hi = std::stoi(token.substr(dash + 1));
                // LED-101: an out-of-range upper bound (e.g. "0-100" on an 8-core
                // device) must not insert non-existent CPUs into the affinity set.
                // Clamp the window to [0, maxCpu] and skip degenerate ranges.
                if (lo < 0) lo = 0;
                if (hi > maxCpu) hi = maxCpu;
                if (lo <= hi) {
                    for (int c = lo; c <= hi; c++) cpus.insert(c);
                }
            } catch (...) {
                static int n = 0; if ((++n & 0x3F) == 1)
                    LOG_DEBUG("parseAffinityMask: range token '%s' unparsable (throttled)", token.c_str());
            }
        } else {
            try {
                int one = std::stoi(token);
                // LED-101: clamp a bare single CPU id as well.
                if (one >= 0 && one <= maxCpu) cpus.insert(one);
            } catch (...) {
                static int n = 0; if ((++n & 0x3F) == 1)
                    LOG_DEBUG("parseAffinityMask: token '%s' unparsable (throttled)", token.c_str());
            }
        }
    }
    return cpus;
}

// P0-1: Read thread affinity via sched_getaffinity() syscall (native, no file I/O)
// Returns set of CPU IDs the thread is allowed to run on.
// parseAffinityMask() is retained for other uses (e.g. config parsing).
// P1-1: returns cpu_set_t directly (stack, no heap allocation).
// Callers use CPU_ISSET(cpu, &mask) instead of set<int>::find().
cpu_set_t getThreadAffinityCpus(int tid) {
    cpu_set_t mask;
    CPU_ZERO(&mask);
    // P2 : check the return value. On failure (e.g. thread already
    // exited, or pid not visible) return an empty mask rather than trusting
    // whatever garbage was on the stack; callers treat an all-zero mask as
    // "no affinity info available".
    if (sched_getaffinity(tid, sizeof(mask), &mask) != 0) {
        CPU_ZERO(&mask);
    }
    return mask;
}

// P1-15: Cached current-CPU reader with pid_tid composite key + steady_clock.
// Composite key prevents TID-reuse collisions (same tid, different pid).
// steady_clock is monotonic and immune to system time changes (unlike time(nullptr)).
int readThreadCurrentCpu(int pid, int tid) {
    // P2-3 fix: use an explicit (pid,tid) pair as the map key instead of the
    // old (pid<<22 | tid) bit-pack. The bit-pack collided/truncated once pid or
    // tid neared the 22-bit mask, which could serve a stale cached CPU across a
    // TID-reuse. std::pair<int,int> has operator< and is exact for all valid
    // pid/tid values on the platform.
    static std::map<std::pair<int,int>, std::pair<int, unsigned long long>> s_cpuCache; // key -> {cpu, steady_ms}
    static std::mutex s_cacheMutex;
    static unsigned long long s_lastPurgeMs = 0;
    unsigned long long nowMs = (unsigned long long)std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
    auto key = std::make_pair(pid, tid);
    {
        std::lock_guard<std::mutex> lock(s_cacheMutex);
        // Time-based purge: even on cache hits, sweep expired entries at most
        // once per 30s so the map does not grow unboundedly when threads are
        // read repeatedly without new inserts.
        if (nowMs - s_lastPurgeMs >= 30000ULL) {
            s_lastPurgeMs = nowMs;
            const unsigned long long kMaxAgeMs = 60000ULL;
            for (auto it = s_cpuCache.begin(); it != s_cpuCache.end(); ) {
                if (nowMs - it->second.second > kMaxAgeMs) {
                    it = s_cpuCache.erase(it);
                } else {
                    ++it;
                }
            }
        }
        auto it = s_cpuCache.find(key);
        if (it != s_cpuCache.end() && (nowMs - it->second.second) < (cpu_cache::kCacheTtlSec * 1000ULL)) {
            return it->second.first; // cache hit
        }
    }
    std::string statPath = "/proc/" + std::to_string(pid) + "/task/" + std::to_string(tid) + "/stat";
    std::ifstream f(statPath);
    if (!f) return -1;
    // In /proc/[pid]/stat, processor is field 39 (1-based, counting pid and
    // comm as fields 1 and 2). After stripping "pid (comm) ", the remaining
    // tokens start at state=0, so processor lands at 0-indexed position 36.
    // Format: pid (comm) state ppid ... processor (0-indexed 36 after comm)
    std::string content;
    std::getline(f, content);
    // Find the closing paren of comm field
    size_t paren = content.rfind(')');
    if (paren == std::string::npos) return -1;
    std::string rest = content.substr(paren + 1);
    std::stringstream ss(rest);
    std::string field;
    int idx = 0; // field 0 = state (after comm)
    int processor = -1;
    while (ss >> field) {
        if (idx == 36) { // state(0)+ppid(1)+pgrp(2)+session(3)+tty_nr(4)+tpgid(5)+flags(6)+minflt(7)+cminflt(8)+majflt(9)+cmajflt(10)+utime(11)+stime(12)+cutime(13)+cstime(14)+priority(15)+nice(16)+num_threads(17)+itrealvalue(18)+starttime(19)+vsize(20)+rss(21)+rsslim(22)+startcode(23)+endcode(24)+startstack(25)+kstkesp(26)+kstkeip(27)+signal(28)+blocked(29)+sigignore(30)+sigcatch(31)+wchan(32)+nswap(33)+cnswap(34)+exit_signal(35)+processor(36)
            try { processor = std::stoi(field); }
            catch (...) {
                static int n = 0; if ((++n & 0x3F) == 1)
                    LOG_DEBUG("readThreadCurrentCpu: stat field36='%s' unparsable (throttled)", field.c_str());
            }
            break;
        }
        idx++;
    }
    // P1-15: write result to cache with composite key + steady_clock timestamp.
    // Expired-entry purge is handled by the time-based sweep at the top of this
    // function (runs on both hit and miss paths at most once per 30s).
    if (processor >= 0) {
        std::lock_guard<std::mutex> lock(s_cacheMutex);
        s_cpuCache[key] = {processor, nowMs};
    }
    return processor;
}

